import {
    LexicalTypeaheadMenuPlugin,
    type MenuRenderFn,
    type TriggerFn,
} from '@lexical/react/LexicalTypeaheadMenuPlugin'
import { useCellValue } from '@mdxeditor/editor'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext';
import { COMMAND_PRIORITY_HIGH, type TextNode } from 'lexical';
import { createPortal } from 'react-dom'
import { useCallback, useEffect, useMemo, useState } from 'react';
import { RESET_MARKDOWN_DRAFT_COMMAND } from '../data_sources/reset_markdown_draft_command';
import type { ActionPlaceholder } from '../../../data/action_placeholders'
import { formatActionPlaceholder } from '../../../data/action_placeholders'
import { markdownPlaceholderConfig$ } from './markdown_placeholder_config_cell'
import { MarkdownPlaceholderOption } from './markdown_placeholder_option'
import { MarkdownPlaceholderMenu } from './markdown_placeholder_menu'
import { matchPlaceholderTrigger } from './markdown_placeholder_trigger'

function placeholderMatchesQuery(placeholder: ActionPlaceholder, query: string) {
    return placeholder.name.toLocaleLowerCase().includes(query.toLocaleLowerCase())
}

/** Shows supported placeholders at the caret after the user types `{{`. */
export function MarkdownPlaceholderTypeaheadPlugin() {
    const [editor] = useLexicalComposerContext();
    const { overlayContainer, placeholders } = useCellValue(markdownPlaceholderConfig$)
    const [query, setQuery] = useState('')
    const options = useMemo(
        () => placeholders
            .filter((placeholder) => placeholderMatchesQuery(placeholder, query))
            .map((placeholder) => new MarkdownPlaceholderOption(placeholder)),
        [placeholders, query],
    )

    const triggerFn = useCallback<TriggerFn>((text, editor) => {
        const match = matchPlaceholderTrigger(text, editor)
        if (!match || !placeholders.some((placeholder) => placeholderMatchesQuery(placeholder, match.matchingString))) return null

        return match
    }, [placeholders])

    const handleQueryChange = useCallback((nextQuery: string | null) => {
        setQuery(nextQuery ?? '')
    }, [])

    const handleDraftReset = useCallback(() => {
        setQuery('');
        return false;
    }, []);
    useEffect(() => editor.registerCommand(RESET_MARKDOWN_DRAFT_COMMAND, handleDraftReset, COMMAND_PRIORITY_HIGH),
        [editor, handleDraftReset]);

    const handleSelectOption = useCallback((
        option: MarkdownPlaceholderOption,
        textNodeContainingQuery: TextNode | null,
        closeMenu: () => void,
    ) => {
        if (!textNodeContainingQuery) return

        textNodeContainingQuery.setTextContent(formatActionPlaceholder(option.placeholder.name))
        textNodeContainingQuery.selectEnd()
        closeMenu()
    }, [])

    const renderMenu = useCallback<MenuRenderFn<MarkdownPlaceholderOption>>((anchorElementRef, itemProps) => {
        if (!anchorElementRef.current || itemProps.options.length === 0) return null

        return createPortal(
            <MarkdownPlaceholderMenu
                onHighlight={itemProps.setHighlightedIndex}
                onSelect={itemProps.selectOptionAndCleanUp}
                options={itemProps.options}
                selectedIndex={itemProps.selectedIndex}
            />,
            anchorElementRef.current,
        )
    }, [])

    return (
        <LexicalTypeaheadMenuPlugin<MarkdownPlaceholderOption>
            menuRenderFn={renderMenu}
            onQueryChange={handleQueryChange}
            onSelectOption={handleSelectOption}
            options={options}
            parent={overlayContainer ?? undefined}
            triggerFn={triggerFn}
        />
    )
}

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import type { ActionPlaceholder } from '../../../data/action_placeholders'
import { markdownPlaceholderConfig$ } from './markdown_placeholder_config_cell'
import { MarkdownPlaceholderTypeaheadPlugin } from './markdown_placeholder_typeahead_plugin'

interface MarkdownPlaceholderPluginParams {
    overlayContainer?: HTMLElement | null
    placeholders: readonly ActionPlaceholder[]
}

/** Connects placeholder configuration and caret typeahead to an MDXEditor realm. */
export const markdownPlaceholderPlugin = realmPlugin<MarkdownPlaceholderPluginParams>({
    init(realm, params) {
        if (!params) throw new Error('Markdown placeholder plugin requires parameters')

        realm.register(markdownPlaceholderConfig$)
        realm.pub(markdownPlaceholderConfig$, params)
        realm.pub(addComposerChild$, MarkdownPlaceholderTypeaheadPlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown placeholder plugin requires parameters')

        realm.pub(markdownPlaceholderConfig$, params)
    },
})

import DataObjectOutlined from '@mui/icons-material/DataObjectOutlined'
import { IconButton, Menu, MenuItem, Tooltip } from '@mui/material'
import { activeEditor$, useCellValue } from '@mdxeditor/editor'
import { CONTROLLED_TEXT_INSERTION_COMMAND } from 'lexical'
import { useState, type MouseEvent } from 'react'
import type { ActionPlaceholder } from '../../../data/action_placeholders'
import { formatActionPlaceholder } from '../../../data/action_placeholders'
import { dialogService } from '../../../services/dialog_service'

interface MarkdownPlaceholderToolbarControlProps {
    overlayContainer?: HTMLElement | null
    placeholders: readonly ActionPlaceholder[]
}

/** Toolbar menu that inserts a supported action placeholder at the active selection. */
export function MarkdownPlaceholderToolbarControl(props: MarkdownPlaceholderToolbarControlProps) {
    const { overlayContainer, placeholders } = props
    const activeEditor = useCellValue(activeEditor$)
    const [anchorElement, setAnchorElement] = useState<HTMLElement | null>(null)

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        setAnchorElement(event.currentTarget)
    }

    const handleClose = () => {
        setAnchorElement(null)
    }

    const handlePlaceholderClick = (event: MouseEvent<HTMLElement>) => {
        try {
            const placeholderName = event.currentTarget.dataset.placeholderName
            const placeholder = placeholders.find(({ name }) => name === placeholderName)
            if (!placeholder) throw new Error(`Unknown Markdown placeholder: ${placeholderName}`)
            if (!activeEditor) throw new Error('Cannot insert a placeholder without an active Markdown editor')

            activeEditor.dispatchCommand(CONTROLLED_TEXT_INSERTION_COMMAND, formatActionPlaceholder(placeholder.name))
            activeEditor.focus()
            handleClose()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Markdown placeholder could not be inserted' })
        }
    }

    return (
        <>
            <Tooltip title="Insert placeholder">
                <span>
                    <IconButton
                        aria-controls={anchorElement ? 'markdown-placeholder-menu' : undefined}
                        aria-expanded={!!anchorElement}
                        aria-haspopup="menu"
                        aria-label="Insert placeholder"
                        disabled={!activeEditor}
                        onClick={handleOpen}
                        size="small"
                    >
                        <DataObjectOutlined fontSize="small" />
                    </IconButton>
                </span>
            </Tooltip>
            <Menu
                anchorEl={anchorElement}
                container={overlayContainer ?? undefined}
                id="markdown-placeholder-menu"
                onClose={handleClose}
                open={!!anchorElement}
            >
                {placeholders.map((placeholder) => (
                    <MenuItem
                        data-placeholder-name={placeholder.name}
                        key={placeholder.name}
                        onClick={handlePlaceholderClick}
                        sx={{ alignItems: 'flex-start', display: 'flex', flexDirection: 'column' }}
                    >
                        <code>{formatActionPlaceholder(placeholder.name)}</code>
                        <small>{placeholder.description}</small>
                    </MenuItem>
                ))}
            </Menu>
        </>
    )
}

