/**
 * Body editing surface for a card, bound directly to the card Markdown data source.
 */
export const CardBodyEditor = memo(function CardBodyEditor(props: CardBodyEditorProps) {
    const {cardTypes, dataSource, historyStore, isFullscreen, isMobile = false, onToggleFullscreen, overlayContainer, statusColors} = props
    const readOnly = useProjectReadOnly()
    const handleImagePaste = useCallback(
        (file: File, insertMarkdown: (markdown: string) => void) => dataSource.pasteImage('board-card', file, insertMarkdown),
        [dataSource],
    )
    const handleAttachments = useCallback((files: File[], insertMarkdown: (markdown: string) => void) => {
        const card = dataSource.getActiveCard('board-card')
        if (!card) throw new Error('Cannot attach files without an active board card')

        return attachFilesToCardMarkdown(card.path, files, insertMarkdown)
    }, [dataSource])
    const handleImagePreview = useCallback(async (src: string) => {
        const card = dataSource.getActiveCard('board-card')
        if (!card) return src

        return resolveCardImageSource(card.path, src)
    }, [dataSource])
    const ToolbarContents = useCallback(
        (toolbarContext: MarkdownToolbarContext) => (
            <CardPopupToolbarControls
                cardTypes={cardTypes}
                dataSource={dataSource}
                isFullscreen={isFullscreen}
                isMobile={isMobile}
                onAttachFiles={toolbarContext.onAttachFiles}
                onToggleFullscreen={onToggleFullscreen}
                readOnly={readOnly}
                statusColors={statusColors}
            />
        ),
        [cardTypes, dataSource, isFullscreen, isMobile, onToggleFullscreen, readOnly, statusColors],
    )
    return (
        <Box
            sx={{
                '& .mdxeditor-content': {
                    boxSizing: 'border-box',
                    minHeight: 220,
                    padding: '26px 28px 32px',
                },
                '& [class*="_toolbarButton_"], & [class*="_toolbarToggleItem_"]': {
                    alignItems: 'center',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    display: 'flex',
                    height: 30,
                    justifyContent: 'center',
                    width: 30,
                },
                '& [class*="_toolbarButton_"]:hover, & [class*="_toolbarToggleItem_"]:hover': {
                    backgroundColor: 'background.paper',
                    color: 'text.primary',
