function capturedImagePreviewHandler() {
    const options = imagePluginSpy.mock.calls[imagePluginSpy.mock.calls.length - 1]?.[0]
    if (!options?.imagePreviewHandler) throw new Error('Expected image preview handler')

    return options.imagePreviewHandler
}

function capturedSearchPopperProps() {
    const calls = popperPropsSpy.mock.calls.filter(([props]) => props.role === 'dialog')
    const call = calls[calls.length - 1]
    if (!call) throw new Error('Expected local-search Popper props')

    return call[0]
}

describe('CardBodyEditor', () => {
    const target = { document: { kind: 'card' } } as MarkdownDocumentTarget

    beforeEach(() => {
        cardMarkdownDataSource.setActiveTarget('board-card', target)
        vi.spyOn(cardMarkdownDataSource, 'getMarkdown').mockReturnValue('# Alpha\n\nOriginal body')
        vi.spyOn(cardMarkdownDataSource, 'edit').mockImplementation(() => undefined)
        vi.spyOn(cardMarkdownDataSource, 'commit').mockReturnValue(true)
        vi.spyOn(cardMarkdownDataSource, 'getActiveCard').mockReturnValue(null)
    })

    afterEach(() => {
        cleanup()
        cardMarkdownDataSource.setActiveTarget('board-card', null)
        vi.restoreAllMocks()
    })

    it('resolves a relative image source beside the active card to a data URI', async () => {
        const loadProjectAsset = vi.spyOn(dataService.projectLoading, 'loadProjectAsset').mockResolvedValue({
            content: 'aW1hZ2U=',
            contentType: 'image/png',
            encoding: 'base64',
            path: 'design/active/pasted-image-1.png',
        })
        renderCardBodyEditor(editorProps())
        const activeCard = { path: 'design/active/card.md' } as ActiveCard
        vi.mocked(cardMarkdownDataSource.getActiveCard).mockReturnValue(activeCard)

        const source = await capturedImagePreviewHandler()('pasted-image-1.png')

        expect(source).toBe('data:image/png;base64,aW1hZ2U=')
        expect(loadProjectAsset).toHaveBeenCalledWith('design/active/pasted-image-1.png')
        expect(screen.getByRole('textbox')).toHaveValue('# Alpha\n\nOriginal body')
    })

    it('loads body through board-card data source binding', () => {
        renderCardBodyEditor(editorProps())

        expect(screen.getByRole('textbox')).toHaveValue('# Alpha\n\nOriginal body')
        expect(screen.getByTestId('create-link').nextElementSibling).toContainElement(screen.getByRole('button', { name: 'Attach files' }))
        expect(cardMarkdownDataSource.getMarkdown).toHaveBeenCalledWith(target)
    })

    it('commits outgoing document target when editor unmounts', () => {
        const { unmount } = renderCardBodyEditor(editorProps())
        fireEvent.change(screen.getByRole('textbox'), { target: { value: '# Alpha\n\nEdited body' } })

        unmount()

        expect(cardMarkdownDataSource.commit).toHaveBeenCalledWith('board-card', target, '# Alpha\n\nEdited body')
    })

    it.each([
        { isMobile: false, layout: 'desktop' },
        { isMobile: true, layout: 'mobile' },
    ])('keeps toolbar sticky on $layout', ({ isMobile }) => {
        const { container } = renderCardBodyEditor(editorProps({ isMobile }))

        expect(container.querySelector('[data-sticky-toolbar="true"]')).not.toBeNull()
    })

    it('anchors local search below its sticky toolbar', () => {
        const { container } = renderCardBodyEditor(editorProps())
        const toolbar = container.querySelector<HTMLElement>('.mdxeditor-toolbar')
        if (!toolbar) throw new Error('Expected sticky card Markdown toolbar')

        fireEvent.click(screen.getByRole('button', { name: 'Find text' }))

        const popperProps = capturedSearchPopperProps()
        expect(popperProps.anchorEl).toBe(toolbar)
        expect(popperProps.placement).toBe('bottom-end')
    })

    it('hides fullscreen control on mobile', () => {
        renderCardBodyEditor(editorProps({ isMobile: true }))

        expect(screen.queryByRole('button', { name: 'Fullscreen' })).not.toBeInTheDocument()
    })

    it('keeps fullscreen control on desktop', () => {
        renderCardBodyEditor(editorProps())

        expect(screen.getByRole('button', { name: 'Fullscreen' })).toBeInTheDocument()
    })
})

