interface MarkdownPlaceholderOptionItemProps {
    index: number
    onHighlight: (index: number) => void
    onSelect: (option: MarkdownPlaceholderOption) => void
    placeholder: ActionPlaceholder
    selectionOption: MarkdownPlaceholderOption
    selected: boolean
